function textOf(value) {
  if (value == null) return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(textOf).join(', ');
  if (typeof value === 'object') {
    if (typeof value.text === 'string') return value.text;
    if (typeof value.address === 'string') return value.address;
    if (Array.isArray(value.value)) return value.value.map(textOf).join(', ');
  }
  return String(value);
}

function header(json, name) {
  const headers = json.headers ?? json.header ?? {};
  const key = Object.keys(headers).find((item) => item.toLowerCase() === name.toLowerCase());
  return key ? textOf(headers[key]) : '';
}

function asBuffer(value) {
  if (Buffer.isBuffer(value)) return value;
  if (value instanceof Uint8Array) return Buffer.from(value);
  if (value && Array.isArray(value.data)) return Buffer.from(value.data);
  if (typeof value === 'string') {
    if (/OFXHEADER|<OFX|<STMTTRN/i.test(value)) return Buffer.from(value, 'utf8');
    return Buffer.from(value, 'base64');
  }
  throw new Error('Não foi possível ler os bytes do anexo OFX.');
}

function decodeOfx(bytes) {
  if (bytes.length >= 2 && bytes[0] === 0xff && bytes[1] === 0xfe) {
    return bytes.subarray(2).toString('utf16le');
  }
  if (bytes.length >= 2 && bytes[0] === 0xfe && bytes[1] === 0xff) {
    const swapped = Buffer.alloc(bytes.length - 2);
    for (let i = 2; i + 1 < bytes.length; i += 2) {
      swapped[i - 2] = bytes[i + 1];
      swapped[i - 1] = bytes[i];
    }
    return swapped.toString('utf16le');
  }
  const pairs = Math.floor(Math.min(bytes.length, 64) / 2);
  let oddZero = 0;
  let evenZero = 0;
  for (let i = 0; i < pairs; i++) {
    if (bytes[i * 2] === 0) evenZero += 1;
    if (bytes[i * 2 + 1] === 0) oddZero += 1;
  }
  if (pairs >= 8 && oddZero > pairs * 0.6 && evenZero < pairs * 0.2) {
    return bytes.toString('utf16le');
  }
  if (pairs >= 8 && evenZero > pairs * 0.6 && oddZero < pairs * 0.2) {
    const swapped = Buffer.alloc(bytes.length - (bytes.length % 2));
    for (let i = 0; i + 1 < bytes.length; i += 2) {
      swapped[i] = bytes[i + 1];
      swapped[i + 1] = bytes[i];
    }
    return swapped.toString('utf16le');
  }
  const utf8 = bytes.toString('utf8');
  return utf8.includes('\uFFFD') ? bytes.toString('latin1') : utf8;
}

const input = $input.all();
const items = [];
for (let itemIndex = 0; itemIndex < input.length; itemIndex++) {
  const item = input[itemIndex];
  const json = item.json ?? {};
  const recipient = [
    textOf(json.to),
    textOf(json.deliveredTo),
    header(json, 'to'),
    header(json, 'delivered-to'),
    header(json, 'x-original-to'),
    header(json, 'envelope-to'),
  ].find((value) => value.includes('+') && value.includes('@')) ?? textOf(json.to) ?? header(json, 'to');

  const plus = /\+([a-z0-9]{8})@/i.exec(recipient);
  const token = plus ? plus[1].toLowerCase() : 'missing';
  const messageId = textOf(json.messageId) || header(json, 'message-id') || `generated-${Date.now()}`;
  const gmailMessageId = textOf(json.id);
  const binaries = item.binary ?? {};

  for (const [key, file] of Object.entries(binaries)) {
    const fileName = String(file.fileName ?? key);
    const mime = String(file.mimeType ?? '');
    if (!/\.ofx$/i.test(fileName) && !/ofx/i.test(mime)) continue;

    const bytes = asBuffer(await this.helpers.getBinaryDataBuffer(itemIndex, key));
    const text = decodeOfx(bytes);
    if (!/OFXHEADER|<OFX|<STMTTRN/i.test(text)) {
      const preview = text.replace(/\s+/g, ' ').trim().slice(0, 80);
      throw new Error(`Anexo sem OFX legível (${preview || 'vazio'}).`);
    }
    items.push({
      json: {
        token,
        recipientAddress: recipient || 'unknown',
        messageId: `${messageId}:${fileName}`.slice(0, 300),
        fileName,
        attachment: Buffer.from(text, 'utf8').toString('base64'),
        gmailMessageId,
      },
    });
  }
}
return items;
